import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-article-form',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>{{ isEdit ? 'Sửa' : 'Tạo' }} bài viết</h2></div></div>
    <section class="section">
      <div class="container container-sm">
        <div class="card"><div class="card-body">
          <form (ngSubmit)="save()">
            <div class="form-group"><label>Tiêu đề *</label><input type="text" class="form-control" [(ngModel)]="form.title" name="title" required></div>
            <div class="form-group"><label>Danh mục *</label><select class="form-control" [(ngModel)]="form.categoryId" name="categoryId" required><option value="">Chọn danh mục</option><option *ngFor="let c of categories" [value]="c.id">{{ c.name }}</option></select></div>
            <div class="form-group"><label>Tóm tắt</label><textarea class="form-control" [(ngModel)]="form.excerpt" name="excerpt" rows="2"></textarea></div>
            <div class="form-group"><label>Nội dung HTML *</label><textarea class="form-control" [(ngModel)]="form.content" name="content" rows="10" required></textarea></div>
            <div class="form-group"><label>URL hình ảnh</label><input type="text" class="form-control" [(ngModel)]="form.imageUrl" name="imageUrl"></div>
            <div class="form-group"><label>Tags (comma-separated)</label><input type="text" class="form-control" [(ngModel)]="form.tags" name="tags" placeholder="VD: sapa,mùa lúa chín"></div>
            <div class="form-group"><label><input type="checkbox" [(ngModel)]="form.isFeatured"> Nổi bật</label></div>
            <div class="form-group"><label><input type="checkbox" [(ngModel)]="form.isPublished"> Xuất bản</label></div>
            <div style="display:flex;gap:0.75rem;"><button type="submit" class="btn btn-primary" [disabled]="loading">{{ loading ? 'Đang lưu...' : 'Lưu' }}</button><a routerLink="/admin/articles" class="btn btn-outline">Hủy</a></div>
          </form>
        </div></div>
      </div>
    </section>
  `
})
export class ArticleFormComponent implements OnInit {
  isEdit = false;
  form: any = { isFeatured: false, isPublished: true };
  categories: any[] = [];
  loading = false;
  constructor(private api: ApiService, private route: ActivatedRoute, private router: Router) {}
  ngOnInit() {
    this.api.getArticleCategories().subscribe(d => { this.categories = d; });
    const id = this.route.snapshot.paramMap.get('id');
    if (id) { this.isEdit = true; this.api.getArticle(id).subscribe(d => { this.form = { ...d }; }); }
  }
  save() {
    this.loading = true;
    const action = this.isEdit ? this.api.updateArticle(this.form.id, this.form) : this.api.createArticle(this.form);
    action.subscribe({ next: () => this.router.navigate(['/admin/articles']), error: () => { this.loading = false; } });
  }
}
